"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["11307"],{20678(e){e.exports=JSON.parse('{"id":"FIN-568","slug":"pretax-income","term":"Pretax Income","also_known_as":[],"difficulty":"Intermediate","definition":"Pretax income is a company\'s profit before income tax expense is deducted. It is also called profit before tax or earnings before tax.","explanation":["Pretax income sits near the bottom of the income statement. It is calculated by starting with revenue, subtracting cost of sales and operating expenses to reach operating income, then adding or subtracting non-operating items such as interest income, interest expense and investment gains or losses.","For example, a company with operating income of 2 million, interest expense of 300,000 and interest income of 50,000 has pretax income of 1.75 million.","Income tax expense is then deducted from pretax income to arrive at net income.","Pretax income is useful for comparing companies that face different tax rates, because it removes the effect of tax differences. It is also the starting point for calculating a company\'s effective tax rate: income tax expense divided by pretax income.","Pretax income differs from EBIT because it is calculated after interest. A company with a lot of debt will have a larger gap between EBIT and pretax income than a similar company with little debt."],"note":"","total":1500,"prev":{"slug":"present-value","term":"Present Value"},"next":{"slug":"price-ceiling","term":"Price Ceiling"}}')}}]);